CREATE TABLE points_of_interest (poi_id VARCHAR(36) PRIMARY KEY, name VARCHAR(255) NOT NULL, description VARCHAR(2000), qr_code VARCHAR(100) NOT NULL UNIQUE, created_at VARCHAR(35) NOT NULL, updated_at VARCHAR(35) NOT NULL);
CREATE TABLE contents (content_id VARCHAR(36) PRIMARY KEY, poi_id VARCHAR(36) NOT NULL, current_version INT NOT NULL, is_deleted BIT NOT NULL DEFAULT 0, created_by VARCHAR(36) NOT NULL, created_at VARCHAR(35) NOT NULL, updated_at VARCHAR(35) NOT NULL, CONSTRAINT fk_content_poi FOREIGN KEY (poi_id) REFERENCES points_of_interest(poi_id));
CREATE TABLE content_versions (content_id VARCHAR(36) NOT NULL, version INT NOT NULL, title VARCHAR(255) NOT NULL, source_lang VARCHAR(20) NOT NULL, text_content VARCHAR(MAX) NOT NULL, created_at VARCHAR(35) NOT NULL, PRIMARY KEY (content_id, version), CONSTRAINT fk_version_content FOREIGN KEY (content_id) REFERENCES contents(content_id));
CREATE TABLE outbox_events (event_id VARCHAR(36) PRIMARY KEY, routing_key VARCHAR(80) NOT NULL, payload VARCHAR(4000) NOT NULL, correlation_id VARCHAR(100), occurred_at VARCHAR(35) NOT NULL, published BIT NOT NULL DEFAULT 0);
